-- SEED: Leads de campaña "Entrega Domingo" (prioridad de contacto).
-- Genera las empresas del Excel LEAD_ENTREGA_DOMINGO como PROSPECCIÓN en la base,
-- marcadas prioridad=true + campania='Entrega Domingo', sin asignar (vendedor_id
-- null) para que la siembra las reparta primero entre los vendedores, sin repetir.
-- Dedup por nombre ALFANUMÉRICO (ignora espacios/símbolos: "Mr Click"="MrClick").
-- Idempotente: re-correr no duplica (matchea por nombre normalizado con guiones).
-- REQUIERE haber corrido antes leads-prioridad.sql.
-- Correr UNA vez en el SQL Editor de Supabase.

create or replace function _clave_nombre(txt text) returns text
language sql immutable as $$
  select regexp_replace(
           regexp_replace(translate(lower(coalesce(txt,'')),'áéíóúüñ','aeiouun'),'[^a-z0-9]+','-','g'),
           '(^-|-$)','','g')
$$;

create temp table _camp (nombre text, comuna text, email text, telefono text, contacto text, score int, nota text) on commit drop;


-- 1) Actualizar las que YA existen (matchea por nombre normalizado con guiones):
update clientes c set
  prioridad = true,
  campania = 'Entrega Domingo',
  prioridad_score = greatest(c.prioridad_score, t.score),
  email    = coalesce(c.email, t.email),
  telefono = coalesce(c.telefono, t.telefono),
  contacto = coalesce(c.contacto, t.contacto),
  comuna   = coalesce(c.comuna, t.comuna)
from _camp t
where _clave_nombre(c.nombre) = _clave_nombre(t.nombre);

-- 2) Insertar las que NO están (prospección, sin asignar, con la marca):
select t.nombre, 'prospeccion', 'mediano', 0, null, t.contacto, t.email, t.telefono, t.comuna, t.nota, true, 'Entrega Domingo', t.score
from _camp t
where not exists (select 1 from clientes c where _clave_nombre(c.nombre) = _clave_nombre(t.nombre));

drop function if exists _clave_nombre(text);

